                Optional.of(new Order(1L, 3_000, Instant.parse("2026-09-01T10:00:00Z"))));

        graphQlTester.document("{ order(id: 1) { status total } }")
                .execute()
                .path("order.status").entity(String.class).isEqualTo("PLACED")
                .path("order.total").entity(Integer.class).isEqualTo(3000);
    }

    @Test
    void aMissingOrderIsNotFound() {
        given(orders.findById(999L)).willReturn(Optional.empty());

        graphQlTester.document("{ order(id: 999) { id } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND);
    }

    // --- Customer.orderCount ---

    @Test
    void orderCountIsTheCustomersNumberOfOrders() {
        given(orders.findById(2L)).willReturn(Optional.of(order(2, 2)));
        given(customers.findAllById(any())).willReturn(List.of(grace()));
        given(orders.countByCustomerIdIn(any()))
                .willReturn(List.of(new CustomerOrderCount(2L, 10L)));

        graphQlTester.document("{ order(id: 2) { customer { id orderCount } } }")
                .execute()
                .path("order.customer.id").entity(String.class).isEqualTo("2")
                .path("order.customer.orderCount").entity(Integer.class).isEqualTo(10);
    }

    @Test
    void orderCountsForAWholePageComeFromOneQuery() {
        List<Order> page = List.of(
                order(1, 1), order(2, 2), order(3, 3), order(4, 1), order(5, 2), order(6, 3));
        given(orders.findBy(any(ScrollPosition.class), any(Limit.class), any(Sort.class)))
                .willReturn(window(page, false));
        given(customers.findAllById(any())).willReturn(List.of(ada(), grace(), linus()));
        // Linus has no row: a customer with no orders still gets a count.
        given(orders.countByCustomerIdIn(any())).willReturn(List.of(
                new CustomerOrderCount(1L, 10L), new CustomerOrderCount(2L, 10L)));

        graphQlTester.document(
                "{ orders(first: 50) { edges { node { customer { id orderCount } } } } }")
                .execute()
                .path("orders.edges[*].node.customer.orderCount").entityList(Integer.class)
                .containsExactly(10, 10, 0, 10, 10, 0);

